"Bravo":{"en":"Well done","es":"Bravo","pt":"Parabéns","de":"Bravo","it":"Bravo","nl":"Goed gedaan","pl":"Brawo","tr":"Tebrikler","ja":"よくできました","ko":"잘했어요","zh":"做得好","ar":"أحسنت","id":"Hebat"},
"Vitamine B6":{"en":"Vitamin B6","es":"Vitamina B6","pt":"Vitamina B6","de":"Vitamin B6","it":"Vitamina B6","nl":"Vitamine B6","pl":"Witamina B6","tr":"B6 vitamini","ja":"ビタミンB6","ko":"비타민 B6","zh":"维生素B6","ar":"فيتامين B6","id":"Vitamin B6"},
