"{n} min restantes":{"en":"{n} min left","es":"Quedan {n} min","pt":"Faltam {n} min","de":"noch {n} Min.","it":"{n} min rimanenti","nl":"nog {n} min","pl":"zostało {n} min","tr":"{n} dk kaldı","ja":"残り{n}分","ko":"{n}분 남음","zh":"剩余 {n} 分钟","ar":"تبقّى {n} د","id":"Sisa {n} mnt"},
